ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT/'lib'));from contracts import *
def pairwin(a,b):return float(a>b)+.5*float(a==b)
def main():
 p=protocol();require(json.loads((ROOT/'validation/independent_cpu_verification.json').read_text())['status']=='PASS','Independentreplayrequired');complete=json.loads((ROOT/'training_completion.json').read_text());require(complete['folds']==24,'Incompleteablation');foldrows=[];long=[]
