 for name,df in [('all_fold_predictions.tsv',pairs),('heldout_individual_predictions.tsv',individual),('metrics.tsv',metric),('per_negative_target.tsv',pd.DataFrame(by_negative)),('per_target_scores.tsv',target),('paired_changes.tsv',delta)]:df.to_csv(ROOT/'results'/name,sep='\t',index=False)
 c=metric[metric.variant=='zero_padded_control'].iloc[0];a=metric[metric.variant=='native_features'].iloc[0];result={'status':'COMPLETE','primary_AUROC_delta':float(a.matched_pair_AUROC-c.matched_pair_AUROC),'balanced_accuracy_delta':float(a.balanced_accuracy_at05-c.balanced_accuracy_at05),'specificity_delta':float(a.specificity_at05-c.specificity_at05),'improved_pairs':int((delta.ranking_change>0).sum()),'worsened_pairs':int((delta.ranking_change<0).sum()),'unchanged_pairs':int((delta.ranking_change==0).sum()),'fold_initial_weights_matched':True,'best_threshold_selection':False,'no_claim12_independent_pairs':True,'code_sha256':sha(__file__),'source_manifest_sha256':frozen(),'result_sha256':{p.name:sha(p) for p in (ROOT/'results').glob('*.tsv')},'biological_validation':False};atomic_json(ROOT/'validation/comparison_receipt.json',result);print(metric.to_string(index=False));print(pd.DataFrame(by_negative).to_string(index=False));print(json.dumps(result,indent=2))
